<script setup lang="ts">
import { computed, ref, nextTick, onMounted, onBeforeUnmount, watch } from 'vue'
import { VueFlow, Handle, Position, useVueFlow, type Connection } from '@vue-flow/core'
import { Background } from '@vue-flow/background'
import { Controls } from '@vue-flow/controls'
import { MiniMap } from '@vue-flow/minimap'
import { Plus, Trash2, Workflow, Code2, Play, Zap, ChevronDown } from 'lucide-vue-next'
import FButton from './fluent/FButton.vue'
import ContextMenu from './ContextMenu.vue'
import { designerClipboard, writeDesignerClipboard } from '../lib/clipboard'
import type { MenuItem } from '../lib/context-menu'
import { clone } from '../lib/model'
import { t } from '../lib/i18n'
import ValueEditor from './ValueEditor.vue'
import { checkConnection, type Editor } from '../lib/editor'
import { createNode, newId, nodeKinds, type FlowNode, type Project, type RuntimeEvent, type ValueRef } from '../lib/model'
import { pluginCatalog, dataPoints } from '../lib/resources'
import { schemaDefault } from '../lib/schema'
import { isMacOS, pythonRuntimeId } from '../lib/platform'
const props = defineProps<{ editor: Editor; events: RuntimeEvent[]; running: boolean; focusNodeId?: string }>()
const emit = defineEmits<{ error: [message: string]; run: [flowId: string, nodeId: string] }>()
const selectedId = ref(''), filter = ref(''), paramsError = ref('')
const readOnly = computed(() => props.editor.readOnly.value)
const viewport = useVueFlow('logic-flow'), flowHost = ref<HTMLElement>(), placement = ref(''), selectedNodes = ref<string[]>([]), contextMenu = ref<{x:number;y:number;items:MenuItem[]}>(), placementPoint = ref<{x:number;y:number}>()
const flow = computed(() => props.editor.flow.value), selected = computed(() => flow.value?.nodes.find(node => node.id === selectedId.value))
const selectedPlugin = computed(() => pluginCatalog.value.find(plugin => plugin.id === props.editor.project.value.connections.find(connection => connection.id === selected.value?.config.connectionId)?.protocolId))
const commands = computed(() => { const items = selectedPlugin.value?.commands; return Array.isArray(items) ? items : Object.entries(items ?? {}).map(([name, value]) => ({ name, ...value })) })
const command = computed(() => commands.value.find(item => item.name === selected.value?.config.command))
const parameterSchema = computed(() => command.value?.params?.properties ?? {})
function selectCommand(name: string) { if (readOnly.value) return; const descriptor = commands.value.find(item => item.name === name); props.editor.mutate(() => { selected.value!.config.command = name; selected.value!.config.params = Object.fromEntries(Object.entries(descriptor?.params?.properties ?? {}).map(([key, schema]: [string, any]) => [key, { source: 'literal', value: schemaDefault(schema) }])) }) }
const filteredKinds = computed(() => nodeKinds.filter(n => n.label.toLowerCase().includes(filter.value.toLowerCase())))
const nodes = computed(() => flow.value?.nodes.map(node => ({ id: node.id, type: 'hmi', position: node.position, data: node, selected: selectedNodes.value.includes(node.id) })) ?? [])
const edges = computed(() => flow.value?.edges.map(edge => ({ id: edge.id, source: edge.source, target: edge.target, sourceHandle: edge.sourcePort, targetHandle: edge.targetPort, type: 'smoothstep', label: edge.sourcePort === 'error' ? '错误' : edge.sourcePort === 'true' ? '是' : edge.sourcePort === 'false' ? '否' : undefined, style: { stroke: edge.sourcePort === 'error' ? '#c74848' : '#8894a2', strokeWidth: 1.6 } })) ?? [])
function addFlow() { if (readOnly.value) return; const id = newId('flow'); if (!props.editor.mutate(p => p.flows.push({ id, name: `新流程 ${p.flows.length + 1}`, enabled: true, timeoutMs: 30000, nodes: [], edges: [] }))) return; props.editor.flowId.value = id; selectedId.value = '' }
function addNode(kind: string, position: {x:number;y:number}) { if (readOnly.value) return; if (!flow.value) addFlow(); if (!flow.value) return; const node = createNode(kind, position); if ('connectionId' in node.config) node.config.connectionId = props.editor.project.value.connections[0]?.id ?? ''; if ('variableId' in node.config) node.config.variableId = props.editor.project.value.variables[0]?.id ?? ''; if ('pageId' in node.config) node.config.pageId = props.editor.project.value.pages[0]?.id ?? ''; if ('widgetId' in node.config) node.config.widgetId = props.editor.page.value.widgets[0]?.id ?? ''; if (!props.editor.mutate(p => { flow.value!.nodes.push(node); if (kind === 'python' && !p.python) p.python = { runtimeId: pythonRuntimeId.value, dependencyLock: [] } })) return; selectedId.value = node.id; selectedNodes.value = [node.id] }
function connect(connection: Connection) { if (readOnly.value || !flow.value) return; const edge = { source: connection.source, target: connection.target, sourcePort: connection.sourceHandle ?? 'out', targetPort: connection.targetHandle ?? 'in' }; const issue = checkConnection(flow.value, edge); if (issue) { emit('error', issue); return }; props.editor.mutate(() => flow.value!.edges.push({ id: newId('edge'), ...edge })) }
function update(key: string, value: unknown) { if (readOnly.value || !selected.value) return; props.editor.mutate(() => selected.value!.config[key] = value) }
function updateLabel(event: Event) { if (readOnly.value || !selected.value) return; props.editor.mutate(() => selected.value!.label = (event.target as HTMLInputElement).value) }
function removeNode() { if (readOnly.value || !selected.value || !flow.value) return; if (!props.editor.mutate(() => { flow.value!.nodes = flow.value!.nodes.filter(n => n.id !== selectedId.value); flow.value!.edges = flow.value!.edges.filter(e => e.source !== selectedId.value && e.target !== selectedId.value) })) return; selectedId.value = '' }
function state(id: string) { const event = [...props.events].reverse().find(event => event.nodeId === id); return event?.kind === 'node.completed' ? 'completed' : event?.kind === 'node.failed' ? 'failed' : event?.kind === 'node.started' ? 'executing' : '' }
function onDragStop(event: any) { if (readOnly.value || !flow.value) return; const dragged = event.nodes?.length ? event.nodes : [event.node]; props.editor.mutate(() => dragged.forEach((node: any) => { const target = flow.value!.nodes.find(n => n.id === node.id); if (target) target.position = { ...node.position } })) }
function params(event: Event) { if (readOnly.value) return; try { const value = JSON.parse((event.target as HTMLTextAreaElement).value); if (!value || Array.isArray(value) || typeof value !== 'object') throw Error('参数必须为对象'); for (const item of Object.values(value)) if (!item || typeof item !== 'object' || !('source' in item)) throw Error('每个参数应使用值来源格式'); update('params', value); paramsError.value = '' } catch (error) { paramsError.value = String(error) } }
const lastNodeEvent = computed(() => [...props.events].reverse().find(event => event.nodeId === selectedId.value))
const configNumber = (event: Event) => Math.max(1, Number((event.target as HTMLInputElement).value))
const fallbackValue: ValueRef = { source: 'literal', value: '' }

async function placeNode(event:MouseEvent|DragEvent,kind=placement.value) { if(!kind||readOnly.value)return; if(!flow.value){addFlow();await nextTick()}const position=viewport.screenToFlowCoordinate({x:event.clientX,y:event.clientY});addNode(kind,{x:Math.round(position.x/8)*8,y:Math.round(position.y/8)*8});placement.value='';placementPoint.value=undefined }
function dropNode(event:DragEvent) { event.preventDefault();const kind=event.dataTransfer?.getData('application/hmi-node')||placement.value;void placeNode(event,kind) }
function flowPaneClick(event:MouseEvent){if(placement.value)void placeNode(event);else{selectedId.value='';selectedNodes.value=[]}}
function nodeClick(event:any){const id=event.node.id;if(event.event?.shiftKey||event.event?.ctrlKey||event.event?.metaKey)selectedNodes.value=selectedNodes.value.includes(id)?selectedNodes.value.filter(value=>value!==id):[...selectedNodes.value,id];else selectedNodes.value=[id];selectedId.value=id}
function copyNodes(cut=false){if(!flow.value)return;const nodes=flow.value.nodes.filter(node=>selectedNodes.value.includes(node.id)),ids=new Set(nodes.map(node=>node.id));writeDesignerClipboard({type:'nodes',projectId:props.editor.project.value.id,nodes:clone(nodes),edges:clone(flow.value.edges.filter(edge=>ids.has(edge.source)&&ids.has(edge.target)))});if(cut)deleteNodes()}
function deleteNodes(){if(!flow.value||!selectedNodes.value.length)return;const ids=new Set(selectedNodes.value);props.editor.mutate(()=>{flow.value!.nodes=flow.value!.nodes.filter(node=>!ids.has(node.id));flow.value!.edges=flow.value!.edges.filter(edge=>!ids.has(edge.source)&&!ids.has(edge.target))});selectedNodes.value=[];selectedId.value=''}
function pasteNodes(point:{x:number;y:number}){const value=designerClipboard.value;if(value?.type!=='nodes'||value.projectId!==props.editor.project.value.id)return;if(!flow.value)addFlow();const ids=new Map(value.nodes.map(node=>[node.id,newId('node')])),left=Math.min(...value.nodes.map(node=>node.position.x)),top=Math.min(...value.nodes.map(node=>node.position.y)),nodes=value.nodes.map(node=>({...clone(node),id:ids.get(node.id)!,position:{x:point.x+node.position.x-left,y:point.y+node.position.y-top}})),edges=value.edges.map(edge=>({...clone(edge),id:newId('edge'),source:ids.get(edge.source)!,target:ids.get(edge.target)!}));props.editor.mutate(()=>{flow.value!.nodes.push(...nodes);flow.value!.edges.push(...edges)});selectedNodes.value=nodes.map(node=>node.id);selectedId.value=nodes[0]?.id??''}
function showContext(event:MouseEvent,nodeId?:string,edgeId?:string){event.preventDefault();event.stopPropagation();placement.value='';if(nodeId&&!selectedNodes.value.includes(nodeId)){selectedNodes.value=[nodeId];selectedId.value=nodeId}const point=viewport.screenToFlowCoordinate({x:event.clientX,y:event.clientY}),items:MenuItem[]=[]
 if(edgeId)items.push({label:'删除连线',action:()=>props.editor.mutate(()=>flow.value!.edges=flow.value!.edges.filter(edge=>edge.id!==edgeId))})
 else if(nodeId){items.push({label:'剪切',action:()=>copyNodes(true)},{label:'复制',action:()=>copyNodes()},{label:'复制副本',action:()=>{copyNodes();pasteNodes({x:point.x+24,y:point.y+24})}},{label:'删除',action:deleteNodes},{label:'断开连线',action:()=>props.editor.mutate(()=>flow.value!.edges=flow.value!.edges.filter(edge=>!selectedNodes.value.includes(edge.source)&&!selectedNodes.value.includes(edge.target)))},{label:'编辑参数',action:()=>document.querySelector<HTMLElement>('.flow-inspector input')?.focus()});if(selected.value?.kind==='python')items.push({label:'编辑代码',action:()=>document.querySelector<HTMLTextAreaElement>('.python-editor')?.focus()});if(selected.value?.kind==='trigger.ui')items.push({label:'触发此入口',disabled:!props.running,action:()=>emit('run',flow.value!.id,nodeId)})}
 else items.push({label:'添加节点',items:nodeKinds.map(kind=>({label:kind.label,action:()=>addNode(kind.kind,point)}))},{label:'在此粘贴',disabled:designerClipboard.value?.type!=='nodes'||designerClipboard.value.projectId!==props.editor.project.value.id,action:()=>pasteNodes(point)})
 items.push({label:'',separator:true},{label:'全选',action:()=>selectedNodes.value=flow.value?.nodes.map(node=>node.id)??[]},{label:'适应画布',action:()=>{void viewport.fitView()}},{label:'实际大小',action:()=>{void viewport.zoomTo(1)}});contextMenu.value={x:event.clientX,y:event.clientY,items}}
function flowKeydown(event:KeyboardEvent){if((event.target as HTMLElement)?.closest('input,textarea,select,[contenteditable=true]'))return;if(event.key==='Escape'){placement.value='';placementPoint.value=undefined;contextMenu.value=undefined}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();deleteNodes()}if(event.ctrlKey||event.metaKey){const key=event.key.toLowerCase();if(key==='c'){event.preventDefault();copyNodes()}if(key==='x'){event.preventDefault();copyNodes(true)}if(key==='a'){event.preventDefault();selectedNodes.value=flow.value?.nodes.map(node=>node.id)??[]}if(key==='v'){event.preventDefault();const rect=flowHost.value?.getBoundingClientRect();if(rect)pasteNodes(viewport.screenToFlowCoordinate({x:rect.left+rect.width/2,y:rect.top+rect.height/2}))}}if(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10'){event.preventDefault();const rect=flowHost.value?.getBoundingClientRect();if(rect)showContext(new MouseEvent('contextmenu',{clientX:rect.left+rect.width/2,clientY:rect.top+rect.height/2}),selectedId.value||undefined)}}
watch(()=>flow.value?.id,()=>{contextMenu.value=undefined;selectedNodes.value=[];placement.value='';selectedId.value=''})
watch(()=>props.focusNodeId,id=>{if(id){selectedId.value=id;selectedNodes.value=[id];void nextTick(()=>viewport.fitView({nodes:[id],maxZoom:1}))}})
onMounted(()=>window.addEventListener('keydown',flowKeydown));onBeforeUnmount(()=>window.removeEventListener('keydown',flowKeydown))

</script>

<template>
  <aside class="library flow-library"><div class="panel-title">流程节点<span class="muted">{{ nodeKinds.length }}</span></div><div class="library-search"><input v-model="filter" placeholder="搜索节点…" aria-label="搜索节点" /></div><div class="node-library-list"><template v-for="group in ['触发','设备','逻辑','代码','输出']" :key="group"><div class="library-section-heading">{{ group }}</div><button v-for="spec in filteredKinds.filter(n => n.group === group)" :key="spec.kind" class="node-library-item" :disabled="readOnly" :draggable="!readOnly" @dragstart="event=>{placement=spec.kind;event.dataTransfer?.setData('application/hmi-node',spec.kind)}" @click="placement=spec.kind"><span :style="{ background: spec.color }" /><Code2 v-if="spec.kind === 'python'" :size="16" /><Zap v-else-if="spec.group === '触发'" :size="16" /><Workflow v-else :size="16" />{{ spec.label }}<Plus :size="13" class="item-add" /></button></template></div><div class="library-footer">连接节点，组织设备交互与数据处理。</div></aside>
  <main ref="flowHost" class="flow-workspace" @dragover.prevent @drop="dropNode" @mousemove="event=>{if(placement)placementPoint={x:event.clientX,y:event.clientY}}"><div class="flow-toolbar"><Workflow :size="16" /><select :value="editor.flowId.value" aria-label="选择流程" @change="editor.flowId.value = ($event.target as HTMLSelectElement).value; selectedId = ''"><option v-if="!editor.project.value.flows.length" value="">暂无流程</option><option v-for="item in editor.project.value.flows" :key="item.id" :value="item.id" data-project-text>{{ item.name }}</option></select><button class="icon-button" title="新建流程" :disabled="readOnly" @click="addFlow"><Plus :size="16" /></button><span class="spacer" /><span class="muted small">{{ flow?.nodes.length ?? 0 }} 个节点 · {{ flow?.edges.length ?? 0 }} 条连线</span></div>
    <VueFlow id="logic-flow" v-if="flow" :key="flow.id" :nodes="nodes" :edges="edges" :nodes-draggable="!readOnly" :nodes-connectable="!readOnly" :delete-key-code="null" fit-view-on-init :min-zoom=".2" :max-zoom="2" @connect="connect" @node-click="nodeClick" @pane-click="flowPaneClick" @node-context-menu="event=>showContext(event.event as MouseEvent,event.node.id)" @pane-context-menu="showContext" @edge-context-menu="event=>showContext(event.event as MouseEvent,undefined,event.edge.id)" @node-drag-stop="onDragStop" @edge-double-click="({ edge }) => { if (!readOnly) editor.mutate(() => flow!.edges = flow!.edges.filter(item => item.id !== edge.id)) }"><Background :gap="20" :size="1" pattern-color="#cdd3da" /><Controls /><MiniMap :pannable="true" :zoomable="true" /><template #node-hmi="{ data }"><div class="flow-node" :class="state(data.id)" :style="{ '--node-color': nodeKinds.find(n => n.kind === data.kind)?.color }"><Handle v-if="!data.kind.startsWith('trigger.')" id="in" type="target" :position="Position.Left" /><div class="flow-node-header"><Code2 v-if="data.kind === 'python'" :size="16" /><Zap v-else-if="data.kind.startsWith('trigger.')" :size="16" /><Workflow v-else :size="16" /><strong data-project-text>{{ data.label }}</strong><span v-if="state(data.id)" class="node-status-dot" /></div><div class="flow-node-caption">{{ nodeKinds.find(n => n.kind === data.kind)?.label }}</div><template v-if="data.kind === 'condition'"><Handle id="true" type="source" :position="Position.Right" :style="{ top: '32%' }" /><Handle id="false" type="source" :position="Position.Right" :style="{ top: '68%' }" /></template><Handle v-else id="out" type="source" :position="Position.Right" /><Handle v-if="!data.kind.startsWith('trigger.')" id="error" type="source" :position="Position.Bottom" class="error-handle" /></div></template></VueFlow>
    <div v-else class="flow-empty" @click="event=>{if(placement)void placeNode(event)}"><Workflow :size="44" stroke-width="1.3" /><h3>让界面与设备协同工作</h3><p>新建流程，从界面事件或定时触发开始。</p><FButton appearance="primary" :disabled="readOnly" @click="addFlow"><Plus :size="16" />新建流程</FButton></div>
<div v-if="placement" class="flow-placement-hint">{{ t('点击画布放置，Esc 取消') }}</div><div v-if="placementPoint && placement" class="flow-placement-ghost" :style="{left:`${placementPoint.x-(flowHost?.getBoundingClientRect().left??0)}px`,top:`${placementPoint.y-(flowHost?.getBoundingClientRect().top??0)}px`}">{{ nodeKinds.find(node=>node.kind===placement)?.label }}</div>
  </main>
  <aside class="inspector flow-inspector"><div class="panel-title">{{ selected ? '节点设置' : '流程设置' }}<button v-if="selected" class="icon-button" title="删除节点" :disabled="readOnly" @click="removeNode"><Trash2 :size="15" /></button></div><div v-if="selected" class="inspector-scroll"><section class="property-section"><label>节点名称<input :value="selected.label" :disabled="readOnly" @change="updateLabel" /></label><p class="node-kind-badge">{{ nodeKinds.find(n => n.kind === selected!.kind)?.label }}</p></section><fieldset class="node-fields" :disabled="readOnly" :inert="readOnly"><section class="property-section">
      <template v-if="selected.kind === 'trigger.ui'"><p class="muted-copy">将按钮的点击事件绑定到此节点，即可启动流程。</p></template>
      <label v-if="selected.kind === 'trigger.timer'">触发间隔（毫秒）<input type="number" min="100" :value="selected.config.intervalMs" @change="update('intervalMs', Math.max(100, configNumber($event)))" /></label>
      <label v-if="selected.kind === 'trigger.data'">数据点<input :value="selected.config.key" placeholder="sensor.temperature" @change="update('key', ($event.target as HTMLInputElement).value)" /></label>
      <template v-if="selected.kind.startsWith('connection.') || selected.kind === 'protocol.command'"><label>连接资源<select :value="selected.config.connectionId" @change="update('connectionId', ($event.target as HTMLSelectElement).value)"><option value="">选择串口连接</option><option v-for="connection in editor.project.value.connections" :key="connection.id" :value="connection.id" data-project-text>{{ connection.name }}</option></select></label></template>
      <template v-if="selected.kind === 'protocol.command'"><label>协议命令<select v-if="commands.length" :value="selected.config.command" @change="selectCommand(($event.target as HTMLSelectElement).value)"><option value="">选择命令</option><option v-for="item in commands" :key="item.name" :value="item.name">{{ item.label || item.name }}</option></select><input v-else :value="selected.config.command" placeholder="命令名称" @change="update('command', ($event.target as HTMLInputElement).value)" /></label><label v-for="(schema, name) in parameterSchema" :key="name">{{ (schema as any).title ?? name }}<ValueEditor :model-value="selected.config.params?.[name] ?? fallbackValue" :project="editor.project.value" @update:model-value="value => editor.mutate(() => { selected!.config.params ??= {}; selected!.config.params[name] = value })" /></label><details class="advanced-params"><summary>参数 JSON</summary><textarea class="code-input" rows="7" :value="JSON.stringify(selected.config.params, null, 2)" spellcheck="false" aria-label="命令参数 JSON" @change="params" /><p class="muted-copy">参数值支持常量、消息字段、控件输入、变量和数据点。</p><p v-if="paramsError" class="error-copy">{{ paramsError }}</p></details></template>
      <template v-if="selected.kind === 'condition'"><label>比较字段<ValueEditor :model-value="selected.config.left ?? fallbackValue" :project="editor.project.value" @update:model-value="update('left', $event)" /></label><label>比较方式<select :value="selected.config.operator" @change="update('operator', ($event.target as HTMLSelectElement).value)"><option value="eq">等于</option><option value="ne">不等于</option><option value="gt">大于</option><option value="gte">大于等于</option><option value="lt">小于</option><option value="lte">小于等于</option><option value="contains">包含</option></select></label><label>目标值<ValueEditor :model-value="selected.config.right ?? fallbackValue" :project="editor.project.value" @update:model-value="update('right', $event)" /></label></template>
      <template v-if="selected.kind.startsWith('variable.')"><label>项目变量<select :value="selected.config.variableId" @change="update('variableId', ($event.target as HTMLSelectElement).value)"><option value="">选择变量</option><option v-for="variable in editor.project.value.variables" :key="variable.id" :value="variable.id" data-project-text>{{ variable.name }}</option></select></label></template>
      <label v-if="['assign', 'variable.get'].includes(selected.kind)">写入消息字段<input :value="selected.config.path" placeholder="payload" @change="update('path', ($event.target as HTMLInputElement).value)" /></label>
      <label v-if="['assign', 'variable.set', 'log'].includes(selected.kind)">值<ValueEditor :model-value="selected.config.value ?? fallbackValue" :project="editor.project.value" @update:model-value="update('value', $event)" /></label>
      <label v-if="selected.kind === 'log'">日志级别<select :value="selected.config.level" @change="update('level', ($event.target as HTMLSelectElement).value)"><option value="info">信息</option><option value="warn">警告</option><option value="error">错误</option></select></label>
      <label v-if="selected.kind === 'delay'">等待时间（毫秒）<input type="number" min="1" :value="selected.config.durationMs" @change="update('durationMs', configNumber($event))" /></label>
      <template v-if="selected.kind === 'python'"><div class="inline-between"><h4>Python 代码</h4><span class="tiny-badge">同步函数</span></div><textarea class="code-input python-editor" rows="16" :value="selected.config.code" spellcheck="false" aria-label="Python 代码" @input="update('code', ($event.target as HTMLTextAreaElement).value)" @keydown.tab.prevent="(event: KeyboardEvent) => { const el = event.target as HTMLTextAreaElement; const start = el.selectionStart; el.setRangeText('    ', start, el.selectionEnd, 'end'); update('code', el.value) }" /><p class="muted-copy">transform(msg) 返回字典继续执行，返回 None 结束当前分支。</p><label>超时（毫秒）<input type="number" min="1" :value="selected.config.timeoutMs" @change="update('timeoutMs', configNumber($event))" /></label><label>{{ isMacOS ? '内存预算（MiB）' : '内存上限（MiB）' }}<input type="number" min="32" :value="selected.config.memoryMb" @change="update('memoryMb', Math.max(32, configNumber($event)))" /></label><p v-if="isMacOS" class="muted-copy">macOS 按进程组 RSS 采样，可能短时超出预算。</p></template>
      <template v-if="selected.kind==='ui.setProperty'"><label>目标控件<select :value="selected.config.widgetId" @change="update('widgetId',($event.target as HTMLSelectElement).value)"><option value="">选择控件</option><template v-for="page in editor.project.value.pages" :key="page.id"><option v-for="widget in page.widgets" :key="widget.id" :value="widget.id" data-project-text>{{page.name}} / {{widget.name}}</option></template></select></label><label>属性<input :value="selected.config.property" placeholder="visible / enabled / activeSlot" @input="update('property',($event.target as HTMLInputElement).value)"/></label><label>目标值<ValueEditor :model-value="selected.config.value ?? fallbackValue" :project="editor.project.value" @update:model-value="update('value',$event)"/></label></template>
      <label v-if="selected.kind === 'page.navigate'">目标页面<select :value="selected.config.pageId" @change="update('pageId', ($event.target as HTMLSelectElement).value)"><option v-for="page in editor.project.value.pages" :key="page.id" :value="page.id" data-project-text>{{ page.name }}</option></select></label>
    </section></fieldset><section v-if="running && selected.kind === 'trigger.ui'" class="property-section"><FButton appearance="primary" @click="emit('run', flow!.id, selected!.id)"><Play :size="14" />触发此入口</FButton></section><section v-if="lastNodeEvent" class="property-section"><h4>最近执行</h4><p class="small">{{ lastNodeEvent.kind }} · {{ lastNodeEvent.runId?.slice(-8) }}</p><pre class="event-detail">{{ JSON.stringify(lastNodeEvent.data, null, 2) }}</pre></section></div>
    <div v-else-if="flow" class="inspector-scroll"><section class="property-section"><label>流程名称<input :value="flow.name" :disabled="readOnly" @change="editor.mutate(() => flow!.name = ($event.target as HTMLInputElement).value)" /></label><label>运行截止时间（毫秒）<input type="number" min="1" :disabled="readOnly" :value="flow.timeoutMs" @change="editor.mutate(() => flow!.timeoutMs = configNumber($event))" /></label><label class="checkbox-label"><input type="checkbox" :checked="flow.enabled" :disabled="readOnly" @change="editor.mutate(() => flow!.enabled = ($event.target as HTMLInputElement).checked)" />启动时启用流程</label></section><section class="property-section"><h4>编辑提示</h4><p class="muted-copy">从输出圆点拖向另一节点的输入圆点以创建连线。底部红点是错误出口。双击连线即可删除。</p><p class="muted-copy">选中节点后，可在这里编辑参数与查看执行结果。流程仅支持无回环连线。</p></section><section class="property-section"><FButton :disabled="readOnly" @click="editor.mutate(p => { p.flows = p.flows.filter(item => item.id !== flow!.id); editor.flowId.value = p.flows[0]?.id ?? '' })"><Trash2 :size="14" />删除当前流程</FButton></section></div>
  </aside>
<ContextMenu v-if="contextMenu" v-bind="contextMenu" @close="contextMenu=undefined"/>
</template>
<style scoped>.flow-placement-hint{position:absolute;top:52px;left:50%;transform:translateX(-50%);padding:7px 12px;background:#e8f2fc;color:#0f6cbd;z-index:5;border-radius:5px;pointer-events:none;font-size:12px}.flow-placement-ghost{position:absolute;pointer-events:none;background:#eef5ffcc;border:2px dashed #0f6cbd;min-width:140px;padding:14px;z-index:10;border-radius:6px}.flow-workspace{min-width:0;overflow:hidden}.flow-inspector{min-height:0}.python-editor{overflow:auto;white-space:pre;min-width:0}</style>
